def tc(fr):
 sec=fr/30;return f'{int(sec//60):02}:{sec%60:05.2f}'
lines=['# Full 7:18.77 storyboard — approval only','','**58 designed information/action beats, NOT 58 forced cuts. Owner approved development; full-film production remains behind asset/animatic quality gates.**','', 'English script and selected natural narration remain unchanged. Timings come from the existing estimated alignment, not a new verified listen-through. Text and sound below are proposed design, not claimed observations from competitor videos.','']
for c in m['chapters']:
 lines += [f'## {c["id"]} · {tc(c["start_frame"])}–{tc(c["start_frame"]+c["frames"])}','']
 for r in (row for row in rows if row['chapter']==c['id']):
  lines += [f'### {r["id"]} · {tc(r["start_frame"])}–{tc(r["end_frame"])}',f'**Narration:** {r["narration"]}','',f'**New visual/task:** {r["new_setup"]}',f'**Meaningful animation:** {r["meaningful_action"]}',f'**Proposed text:** `{r["proposed_short_text"]}`',f'**Flow into next idea:** {r["handoff"]}',f'**Designed sound:** {r["designed_sound_not_observed_competitor_audio"]}','']
  if r['internal_phrase_cues']:
   lines += ['**Internal development (not a static hold):**']
   lines += [f'- On “{cue["spoken_anchor"]}”: {cue["new_information_or_action"]}' for cue in r['internal_phrase_cues']]
   lines += ['']
(B/'FULL-STORYBOARD.md').write_text('\n'.join(lines).rstrip()+'\n')
print('58 proposed compositions; every approved sentence assigned exactly once; 13,163 frames covered; development approved, full-film rendering gated.')
